from queue import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    adj_list = [[] for _ in range(n)]
    for i in range(m):
        u, v = map(int, lines[3 + i].split())
        u -= 1
        v -= 1
        adj_list[u].append(v)
        adj_list[v].append(u)

    source = 0
    sink = 2 * n + 1
    num_nodes = sink + 1

    capacity = {u: {} for u in range(num_nodes)}
    graph = {u: set() for u in range(num_nodes)}

    def add_edge(u, v, cap):
        graph[u].add(v)
        graph[v].add(u)
        capacity[u][v] = cap
        capacity[v][u] = 0

    for i in range(n):
        add_edge(source, i, a[i])
        add_edge(n + i, sink, b[i])

    for i in range(n):
        add_edge(n + i, i, float('inf'))
        for j in range(n):
            if j in adj_list[i]:
                add_edge(n + i, n + j, float('inf'))

    def bfs():
        parent = {}
        for _ in range(num_nodes):
            parent[_] = -1
        parent[source] = source
        q = deque([source])

        while q:
            u = q.popleft()
            for v in graph[u]:
                if capacity[u][v] > 0 and parent[v] == -1:
                    parent[v] = u
                    if v == sink:
                        return parent
                    q.append(v)
        return parent

    def dfs_flow(parent, pushed):
        if pushed == 0:
            return 0
        if parent[sink] == -1:
            return 0

        v = parent[sink]
        if pushed >= capacity[parent[v]][v]:
            flow_to_return = capacity[parent[v]][v]
        else:
            flow_to_return = pushed

        while v != source:
            temp = capacity[v][parent[v]]
            actual_flow = min(flow_to_return, temp)
            flow_to_return -= actual_flow
            v = parent[v]

        v = sink
        while v != source:
            temp = capacity[v][parent[v]]
            capacity[v][parent[v]] -= actual_flow
            u = parent[v]
            capacity[u][v] += actual_flow
            v = parent[u]

        return pushed

    max_flow = 0
    while True:
        parent = bfs()
        parent[sink] = -1
        if parent[sink] == -1:
            break

        reached_sink = False
        for _ in range(num_nodes):
            if bfs() is None:
                break

        while True:
            parent = bfs()
            if parent[sink] == -1:
                break

            flow_limit = float('inf')
            path_nodes = []
            v = sink
            while v != source:
                p = parent[v]
                path_nodes.append(v)
                path_nodes.append(p)
                flow_limit = min(flow_limit, capacity[p][v])
                v = p

            if flow_limit == 0:
                parent[sink] = -1
                break

            v = sink
            while parent[v] != -1:
                p = parent[v]
                capacity[p][v] -= flow_limit
                capacity[v][p] += flow_limit
                v = p

            max_flow += flow_limit

    total_soldiers = sum(a)
    if max_flow != total_soldiers:
        return "NO"

    result = []
    for i in range(n):
        row = []
        for j in range(n):
            if i == j:
                idx = n + i
                src = i
                flow = capacity[src][idx] - capacity[idx][src]
                row.append(flow)
            elif j in adj_list[i]:
                src = n + i
                dst = n + j
                flow = capacity[src][dst] - capacity[dst][src]
                row.append(flow)
            else:
                row.append(0)
        result.append(' '.join(map(str, row)))

    return "YES\n" + '\n'.join(result)

