                adj[u].append(v)
                adj[v].append(u)
        except:
            pass

    used = [False] * (n + 1)
    found_cycles = []

    def find_cycle(start_node):
        visited = {start_node}
        path = [start_node]

        def dfs(node):
            for nxt in adj[node]:
                if nxt == start_node and len(path) >= 2:
                    cycle_len = len(path) + 1
                    if cycle_len >= 3 and cycle_len % 3 != 0:
                        return path + [nxt]

                if nxt not in visited:
                    visited = visited | {nxt}
                    path = path + [nxt]
                    result = dfs(nxt)
                    if result:
                        return result

            return None

        return dfs(start_node)

    for _ in range(k):
        start = None
        for i in range(1, n + 1):
            if not used[i]:
                start = i
                break

        if not start:
            break

        visited_local = {start}
        cycle = find_cycle(start)

        if cycle:
            found_cycles.append(cycle)
            for v in cycle:
                used[v] = True
        else:
            used[start] = True

    if len(found_cycles) >= k:
        cycles = found_cycles[:k]
        output = ['CYCLES']
        for cycle in cycles:
            output.append(str(len(cycle)))
            output.append(' '.join(map(str, cycle)))
        return '\n'.join(output)

    # Find longest path
    max_len = 0
    best_path = []

    visited_times = {}

    def dfs_longest(node, path):
        nonlocal max_len, best_path
        visited_times[node] = len(path)

        for nxt in adj[node]:
            if nxt not in visited_times:
                new_path = path + [nxt]
                dfs_longest(nxt, new_path)

        if len(path) > max_len:
            max_len = len(path)
            best_path = path

    for i in range(1, n + 1):
