        for v in adj[u]:
            if levels[v] == -1:
                levels[v] = levels[u] + 1
                q.append(v)

    # Group vertices by level
    by_level = [[] for _ in range(n + 1)]
    for v in range(1, n + 1):
        by_level[levels[v]].append(v)

    # Greedy independent set construction
    result = []
    for level in range(n + 1):
        candidates = by_level[level]
        candidates.sort()
        for v in candidates:
            valid = True
            for u in result:
                if v in adj[u]:
                    valid = False
                    break
            if valid:
                result.append(v)
                if len(result) == k:
