        result = []
        for v in range(1, n + 1):
            valid = True
            for u in result:
                if v in adj[u]:
                    valid = False
                    break
            if valid:
                result.append(v)
                if len(result) == k:
                    break

    result.sort()
    return f"1\n{' '.join(map(str, result))}\n"

