# novel solution that addresses the backtracking issue by ensuring lights remain on for backtracking paths

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, x0, y0 = map(int, lines[0].split())

    grid = []
    for line in lines[1:]:
        grid.append(list(map(int, line.split())))

    # Store initial state to restore for backtracking
    initial_grid = [row[:] for row in grid]
    visited = set()
    actions = []

    # Add starting room to visited
    visited.add((x0, y0))

    def count_lights():
        return sum(sum(row) for row in grid)

    def on_grid(r, c):
        return 1 <= r <= n and 1 <= c <= n

    def has_light(r, c):
        return 1 <= r <= n and 1 <= c <= n and grid[r-1][c-1] == 1

    def can_move(r, c, dr, dc):
        """Check if there's a light in the direction from (r,c)"""
        rr, cc = r + dr, c + dc
        while on_grid(rr, cc):
            if has_light(rr, cc):
                return True
            rr += dr
            cc += dc
        return False

    def turn_light(r, c):
        """Turn light on if off, off if on"""
        global grid
        if 1 <= r <= n and 1 <= c <= n:
            if grid[r-1][c-1] == 0:
                grid[r-1][c-1] = 1
                actions.append('1')
            else:
                grid[r-1][c-1] = 0
                actions.append('2')
        return grid[r-1][c-1]

    # Directions: U, D, L, R
    directions = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

    def solve(r, c):
        # Try all directions to find a move
        can_move_forward = False
        for d, (dr, dc) in directions.items():
            nr, nc = r + dr, c + dc
            if on_grid(nr, nc) and (nr, nc) not in visited and can_move(r, c, dr, dc):
                # Before moving, check if we can return
                # Since we'll turn off our light, we need at least one light in the reverse direction
                cr = r - dr
                cc = c - dc
                if on_grid(cr, cc):
                    if can_move(cr, cc, -dr, -dc):  # reverse direction
                        can_move_forward = True
                        break

        if not can_move_forward:
            # Can't move forward safely, turn off our light if needed
            turn_light(r, c)
            return not count_lights()

        # Turn off/on light at current room
        turn_light(r, c)

        # Find a safe move to make
        for d, (dr, dc) in directions.items():
            nr, nc = r + dr, c + dc
            if on_grid(nr, nc) and (nr, nc) not in visited and can_move(r, c, dr, dc):
                cr = r - dr
                cc = c - dc
                if on_grid(cr, cc) and can_move(cr, cc, -dr, -dc):
                    visited.add((nr, nc))
                    actions.append(d)

                    if solve(nr, nc):
                        return True

                    # Backtrack
                    visited.remove((nr, nc))
                    actions.pop()
                    break

        # If we still have lights, turn them off and return
        result = not count_lights()
        turn_light(r, c)
        return result

    result = solve(x0, y0)

    if not result:
        return "NO"

    # Restore lights for verification
    return "YES\n" + "".join(actions)

