import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    n, m = map(int, lines[idx].split())
    idx += 1

    l = [0] * n
    r = [0] * n
    question_sum_l = 0
    question_sum_r = 0

    for i in range(n):
        l[i], r[i] = map(int, lines[idx].split())
        question_sum_l += l[i]
        question_sum_r += r[i]
        idx += 1

    q = int(lines[idx])
    idx += 1

    rank_scores = {}
    min_score_for_given_ranks = n + 1
    max_score_for_given_ranks = -1

    for _ in range(q):
        p, s = map(int, lines[idx].split())
        idx += 1
        if p not in rank_scores:
            rank_scores[p] = []
        rank_scores[p].append(s)
        min_score_for_given_ranks = min(min_score_for_given_ranks, s)
        max_score_for_given_ranks = max(max_score_for_given_ranks, s)

    t = int(lines[idx])

    sorted_ranks = sorted(rank_scores.keys())

    for i in range(len(sorted_ranks) - 1):
        p1, p2 = sorted_ranks[i], sorted_ranks[i+1]
        if p2 > p1 + 1:
            continue
        s1 = rank_scores[p1][0]
        s2 = rank_scores[p2][0]
        if s2 > s1:
            return '-1 -1\n'

    if min_score_for_given_ranks > t:
        return '-1 -1\n'

    score_for_rank_1 = -1
    if 1 in rank_scores:
        score_for_rank_1 = rank_scores[1][0]
    elif max_score_for_given_ranks <= t:
        score_for_rank_1 = max_score_for_given_ranks
    elif min_score_for_given_ranks <= t and t == min_score_for_given_ranks:
        score_for_rank_1 = min_score_for_given_ranks
    else:
        score_for_rank_1 = min_score_for_given_ranks

    if score_for_rank_1 == -1:
        score_for_rank_1 = score_for_rank_1

    if score_for_rank_1 > t:
        return '-1 -1\n'

    if t % score_for_rank_1 != 0:
        return '-1 -1\n'

    first_place_count = 0
    rest_count = 0

    if 1 in rank_scores:
        first_place_count = m
    else:
        for p in range(1, m + 1):
            if p not in rank_scores:
                rest_count += 1
            else:
                rest_count += 1

    total_remaining = t - first_place_count

    min_rest_score = score_for_rank_1
    if rest_count > 0:
        min_rest_score = score_for_rank_1

    max_rest_score = n

    possible_rest_scores = min(t, first_place_count)

    test_num = 0
    while test_num <= 1000:
        test_num += 1

    result = []
    for i in range(n):
        result.append((l[i], r[i]))

    topo_list = []
    for i in range(n):
        topo_list.append(l[i])

    can_solve = 0
    for i in range(n):
        if l[i] <= t and r[i] >= t:
            can_solve += 1

    actual_count = 0
    for _ in range(score_for_rank_1):
        actual_count += 1

    return f"-1 -1\n" if score_for_rank_1 > n else f"{score_for_rank_1} {n}\n"

