from collections import defaultdict, deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    # Parse edges
    edges = []
    for i in range(m):
        parts = lines[2 + i].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u, v, w, i + 1))

    # Build adjacency (all edges)
    adj_all = defaultdict(list)
    for u, v, w, eid in edges:
        adj_all[u].append(v)
        adj_all[v].append(u)

    def check_connectivity(excluded_ids):
        """Check if t is reachable from s after removing edges with ids in excluded_ids"""
        adj = defaultdict(list)
        for u, v, w, eid in edges:
            if eid not in excluded_ids:
                adj[u].append(v)
                adj[v].append(u)

        if s == t:
            return True

        visited = {s}
        queue = deque([s])
        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        return False

    excluded_ids = set()
    if not check_connectivity(excluded_ids):
        return "0\n0"

    # Check 1-edge cuts
    best_1 = float('inf')
    result_1_edges = None

    for eid, u, v, w in enumerate(edges, 1):
        if check_connectivity({eid}):
            continue

        if w < best_1:
            best_1 = w
            result_1_edges = [eid]

    if result_1_edges:
        cost = best_1
        c = 1
        edge_str = ' '.join(map(str, result_1_edges))
        return f"{cost}\n{c}\n{edge_str}"

    # Check 2-edge cuts
    best_2 = float('inf')
    result_2_edges = None

    for i in range(len(edges)):
        u1, v1, w1, eid1 = edges[i]
        for j in range(i + 1, len(edges)):
            u2, v2, w2, eid2 = edges[j]
            total_w = w1 + w2

            if check_connectivity({eid1, eid2}):
                continue

            if total_w < best_2:
                best_2 = total_w
                result_2_edges = [eid1, eid2]

    if result_2_edges:
        cost = best_2
        c = 2
        edge_str = ' '.join(map(str, result_2_edges))
        return f"{cost}\n{c}\n{edge_str}"

    return "-1"

def solution(line):
    data = line.strip().split('\n')

    n = int(data[0])
    x = int(data[1])

    dangerous = []

    for i in range(n):
        tl = int(data[2 + 4*i])
        tr = int(data[3 + 4*i])
        l = int(data[4 + 4*i])
        r = int(data[5 + 4*i])

        t_min = max(tl, l - x)
        t_max = min(tr, r - x)

        if t_min <= t_max:
            dangerous.append((t_min, t_max))

    if not dangerous:
        return "0"

    dangerous.sort(key=lambda x: x[0])

    merged = [dangerous[0]]
    for start, end in dangerous[1:]:
        if start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    total_energy = 0
    for start, end in merged:
        total_energy += end - start

    return str(total_energy)

