        return (0, 1) if swapLR else (0, -1)
    elif cmd == 'R':
        return (0, -1) if swapLR else (0, 1)
    return (0, 0)

def solution(input_str):
    """
    Solution for the interactive grid navigation problem with button swaps.

    Args:
        input_str: Concatenated string containing the full interaction

    Returns:
        String of commands needed to navigate from (1,1) to 'F'
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    # Parse header: n m [swapLR [swapUD]]
    header = lines[0].split()
    n = int(header[0])
    m = int(header[1])
    swapLR = int(header[2]) if len(header) > 2 else 0
    swapUD = int(header[3]) if len(header) > 3 else 0

    # Parse grid
    grid = lines[1:n+1]

    # Find finish position
    finish_pos = None
    for i in range(n):
        for j in range(len(grid[i])):
            if grid[i][j] == 'F':
                finish_pos = (i + 1, j + 1)
                break
        if finish_pos:
            break

    if not finish_pos:
        return ""

    start_pos = (1, 1)

    # BFS with each possible swap configuration
    def find_path(lr_swap, ud_swap):
        visited = set([start_pos])
        parent = {start_pos: None}
        queue = deque([(start_pos[0], start_pos[1], "")])

        while queue:
            r, c, path = queue.popleft()

            if (r, c) == finish_pos:
                return path

            for cmd in ['U', 'D', 'L', 'R']:
                dr, dc = get_actual_move_effect(cmd, lr_swap, ud_swap)
                nr, nc = r + dr, c + dc

                if 1 <= nr <= n and 1 <= nc <= m:
                    cell = grid[nr-1][nc-1]
                    if cell != '*':
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            parent[(nr, nc)] = (r, c, cmd)
                            queue.append((nr, nc, path + cmd))

                    if (nr, nc) == finish_pos:
                        # Found path
                        path = path + cmd
                        # Reconstruct and return
                        return reconstruct_path(parent, finish_pos)

        return None

    def reconstruct_path(parent, target):
        path = ""
        curr = target
        while curr != start_pos:
            prev_r, prev_c, cmd = parent[curr]
            path = cmd + path
            curr = (prev_r, prev_c)
        return path

    # Try all possible swap configurations
    for lr_swap in [0, 1]:
        for ud_swap in [0, 1]:
            path = find_path(lr_swap, ud_swap)
            if path:
                return path

    return ""

