    while True:
        changed = False
        scatter_positions = {}  # pos -> ants to scatter

        # First, identify all positions needing scattering
        for pos, cnt in list(grid.items()):
            if cnt >= 4:
                scatter_positions[pos] = cnt

        if not scatter_positions:
            break

        # Apply all scattering for this round
        for pos, cnt in list(scatter_positions.items()):
            x, y = pos
            groups = cnt // 4
            remaining = cnt % 4
            grid[pos] = remaining

            grid[(x - 1, y)] += groups
            grid[(x + 1, y)] += groups
            grid[(x, y - 1)] += groups
            grid[(x, y + 1)] += groups

        # Check if any new positions need processing
        new_scatter = set()
        for pos, cnt in grid.items():
            if cnt >= 4 and pos not in scatter_positions:
                new_scatter.add(pos)

        if not new_scatter:
            break

        # Combine for next iteration
        scatter_positions.update(new_scatter)

    # Answer queries
    results = []
    for line in lines[1:]:
        parts = line.split()
        if len(parts) < 2:
            break
        x = int(parts[0])
