    except ValueError:
        return "NO\n"

    strings = lines[1:]

    # If there aren't exactly n strings, return NO
    if len(strings) != n:
        return "NO\n"

    # Count occurrences of each character across all strings
    char_counter = Counter()
    for s in strings:
        char_counter.update(s)

    # If any character appears more than once across all strings, impossible
    # because single characters must also be most frequent, requiring same count
    if any(count > 1 for count in char_counter.values()):
        return "NO\n"

    # Sort strings for lexicographical minimum
    strings = sorted(strings)

    # Concatenate them
    result = ''.join(strings)

    # Check if each string appears exactly once in the result
    for s in strings:
        if s and result.count(s) != 1:
            return "NO\n"

    return result + "\n"

MOD = 10**9 + 7

def combinations(n, k, modulo):
    if k < 0 or k > n:
        return 0
    numerator = 1
    for i in range(k):
        numerator = (numerator * (n - i)) % modulo
    denominator = 1
    for i in range(k):
        denominator = (denominator * (i + 1)) % modulo
    # modular inverse of denominator
    return (numerator * pow(denominator, modulo - 2, modulo)) % modulo

