        for c in c_divs:
            # Calculate number of r×c subrectangles
            row_subrects = n // r
            col_subrects = m // c
            total_subrects = row_subrects * col_subrects

            if total_subrects == 0:
                continue
            elif total_subrects == 1:
                # Only one rectangle, which equals itself
                count += 1
            else:
                # Check if all rectangles equal the reference (0,0)
                is_equal = True

                for i in range(1, row_subrects):
                    for j in range(col_subrects):
                        start_r = i * r
                        start_c = j * c

                        # Compare rectangle at (start_r, start_c) with (0, 0)
                        for hr in range(r):
