                    best_j = j
                    break

            if best_j != -1:
                ans[best_j] = 'R'
                covered[i] = True

        # If still uncovered, try to cover them from the right
        for i in range(n):
            if covered[i]:
                continue

            # Find the nearest lantern k > i that can illuminate i (k is L, so i >= k - p[k])
            best_k = -1
            for k in range(i + 1, n):
                if p[k] >= k - i:
                    best_k = k
                    break

            if best_k != -1:
                ans[best_k] = 'L'
                covered[i] = True

