    MOD = 10**9 + 7

    # Compute square-free part of each number
    def get_square_free(x):
        result = 1
        temp = x
        d = 2
        while d * d <= temp:
            cnt = 0
            while temp % d == 0:
                temp //= d
                cnt += 1
            if cnt % 2 == 1:
                result *= d
            d += 1
        if temp > 1:
            result *= temp
        return result

    from collections import Counter
    sq_free = [get_square_free(x) for x in a]
    groups = Counter(sq_free)

    group_sizes = list(groups.values())

    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

    # DP approach to count valid arrangements
    # dp[i][j] = arrangements with i elements placed, j conflict zones

    # Use simpler DP: dp[j] = ways with j total conflicts from all groups
    dp = [1]

    for size in group_sizes:
        if size == 1:
            continue
        new_dp = [0] * (len(dp) + size * 2)

        for old_j in range(len(dp)):
            if dp[old_j] == 0:
                continue
            # For current group of size s
            # Try creating k conflicts (0 to s-1)
            for k in range(min(old_j, size - 1) + size + 1):
                ways = nCr(size - 1, min(k, size - 1))
                if k <= old_j + size:
                    new_dp[min(max(old_j + k, 0), len(new_dp) - 1)] = (new_dp[min(max(old_j + k, 0), len(new_dp) - 1)] + dp[old_j] * ways) % MOD

        dp = [sum(new_dp)] + [0]

    return str(sum(dp) % MOD)

