from collections import deque

def solution(n_str):
    """
    Find the minimum number of subtractions to reduce n to 0.
    At each step, we can subtract any digit that appears in the current number.
    """
    n = int(n_str)

    if n == 0:
        return "0\n"

    visited = {n}
    queue = deque([(n, 0)])  # (current_value, distance)

    while queue:
        curr, dist = queue.popleft()

        if curr == 0:
            return str(dist) + "\n"

        # Get all distinct digits in the current number
        s = str(curr)
        distinct_digits = set(s)

        for d_str in distinct_digits:
            d = int(d_str)
            if d > 0:  # Can't subtract 0 (doesn't change the number)
                next_val = curr - d
                if next_val not in visited:
                    visited.add(next_val)
                    queue.append((next_val, dist + 1))

    return "0\n"
